  ],
  "expected_accessibility_effect": "Keyboard users arrowing between radio options will now correctly show/hide conditional fields (email address, mobile number) per WCAG 2.1.1 (Keyboard) and 4.1.2 (Name, Role, Value), matching the behavior for mouse users.",
  "functional_risks": [
    "Minimal: only adds a change listener; no existing behavior altered for click interactions.",
    "The change handler only acts on radio inputs with aria-controls, avoiding side effects on other form controls."
  ],
  "verification_requirements": [
    "Run the frozen journey: seek #reminder, ArrowDown to Text message, ArrowDown to opt-out; verify #conditional-reminder-2 becomes hidden.",
    "Verify mouse clicks still toggle conditionals correctly.",
    "Verify form data for reminder updates to 'none' on opt-out selection."
